const highlightIntro = ["Look out for", "Antara tarikan untuk diperhatikan ialah", "值得留意的看点包括", "注目したいのは", "주요 볼거리는", "Destaques a observar:", "கவனிக்க வேண்டிய சிறப்புகள்:", "Fíjate en", "À découvrir :"];
const listFormatters = new Map<Locale, Intl.ListFormat>();

export function hasDestinationStory(story: Destination["visitorStory"]): boolean {
  return Boolean(story && typeof story.theme === "string" && Array.isArray(themes[story.theme]) && Array.isArray(story.highlights) && story.highlights.length >= 2 && story.highlights.length <= 4 && story.highlights.every(key => typeof key === "string" && Array.isArray(highlights[key])));
}

export function destinationNarrative(destination: Destination, locale: Locale): string | undefined {
  const story = destination.visitorStory;
  if (!hasDestinationStory(story) || !story) return undefined;
  const index = Math.max(0, languages.indexOf(locale));
  const language = languages[index];
  let formatter = listFormatters.get(language);
  if (!formatter) {
    formatter = new Intl.ListFormat(language, { style: "long", type: "conjunction" });
    listFormatters.set(language, formatter);
  }
  const list = formatter.format(story.highlights.map(key => highlights[key][index]));
  const ending = locale === "zh" ? "。" : locale === "ja" ? "です。" : locale === "ko" ? "입니다." : ".";
  return `${themes[story.theme][index]} ${highlightIntro[index]} ${list}${ending}`;
}

export const destinationStoryKeys = { themes: Object.keys(themes), highlights: Object.keys(highlights) };
